window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-38501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2351 na letra σ · nº geral 38501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξυνδέω (fut. συνδήσω, aor. συνέδησα, perf. συνδέδεκα) 1 ligar junto; unir bem 2 amarrar mãos e pés de alguém, ac. 3 enfaixar (ferida) 4 formar de partes ligadas entre si: σ. καλιήν luc. construir um ninho sólido 5 Gram. conectar; coordenar ♦ méd. 6 ligar; unir; atar 7 unir-se a alguém, dat., por algo, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-38502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνδηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2352 na letra σ · nº geral 38502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem evidente. 〈σύν, δῆλος〉</p></section></article>\n<article id=\"entry-dgp-38503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδηλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2353 na letra σ · nº geral 38503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar evidente ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδημαγωγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2354 na letra σ · nº geral 38504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contribuir para dominar ou conquistar o povo: συνεδημαγώγησε τῷ πάθει τοὺς πολλούς plut. com seu infortúnio, conquistou o favor do povo.</p></section></article>\n<article id=\"entry-dgp-38505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαβαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2355 na letra σ · nº geral 38505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atravessar ao mesmo tempo ou com, dat.</p></section></article>\n<article id=\"entry-dgp-38506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιάβαλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2356 na letra σ · nº geral 38506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atravessar junto 2 caluniar, desacreditar ou acusar com ou ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαβιβάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2357 na letra σ · nº geral 38507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer atravessar com ou ao mesmo tempo; ajudar a transportar através.</p></section></article>\n<article id=\"entry-dgp-38508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαγιγνώσκω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2358 na letra σ · nº geral 38508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνδιαγιγνώσκω 1 decidir com alguém dat., algo, inf. 2 distinguir ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιάγω</h1><div class=\"entry-meta\"><span>DGP · ordem 2359 na letra σ · nº geral 38509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levar a vida com alguém, dat. ou μετά e gen., ou algo, dat.</p></section></article>\n<article id=\"entry-dgp-38510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαιρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2360 na letra σ · nº geral 38510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">separar ou dividir ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2361 na letra σ · nº geral 38511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercer o poder de árbitro; concluir uma questão judicial ♦ méd. 2 habitar ou viver com alguém, dat. ou μετά e gen.</p></section></article>\n<article id=\"entry-dgp-38512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαίτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2362 na letra σ · nº geral 38512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitação ou vida comum; relação familiar com alguém, dat. ou μετά e gen. 〈συνδιαιτάω〉</p></section></article>\n<article id=\"entry-dgp-38513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιακαίω</h1><div class=\"entry-meta\"><span>DGP · ordem 2363 na letra σ · nº geral 38513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">queimar com ou ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιακινδυνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2364 na letra σ · nº geral 38514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">correr perigo com alguém, μετά e gen.</p></section></article>\n<article id=\"entry-dgp-38515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιακομίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2365 na letra σ · nº geral 38515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transportar com.</p></section></article>\n<article id=\"entry-dgp-38516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιακοσμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2366 na letra σ · nº geral 38516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pôr em ordem junto; organizar ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιάκτορος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2367 na letra σ · nº geral 38517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ajuda a transportar ou a conduzir, epít. de Hermes.</p></section></article>\n<article id=\"entry-dgp-38518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιάληψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2368 na letra σ · nº geral 38518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deliberação comum. 〈σύν, διαλαμβάνω〉</p></section></article>\n<article id=\"entry-dgp-38519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαλλάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2369 na letra σ · nº geral 38519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω 1 ajudar alguém, dat., a reconciliar uma pessoa, ac., com outra, πρός e ac. ♦ pas. 2 Gram. sofrer alteração junto.</p></section></article>\n<article id=\"entry-dgp-38520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαλύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2370 na letra σ · nº geral 38520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ajudar a fazer cessar ao mesmo tempo (tumulto, cólera) 2 destruir ou dissipar com, dat. ♦ méd. 3 ajudar a pagar.</p></section></article>\n<article id=\"entry-dgp-38521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαμαρτάνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2371 na letra σ · nº geral 38521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">errar a meta junto com alguém.</p></section></article>\n<article id=\"entry-dgp-38522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαμένω</h1><div class=\"entry-meta\"><span>DGP · ordem 2372 na letra σ · nº geral 38522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 permanecer até o fim com 2 ser fixado igualmente.</p></section></article>\n<article id=\"entry-dgp-38523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιανέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 2373 na letra σ · nº geral 38523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">distribuir junto ou com, dat.</p></section></article>\n<article id=\"entry-dgp-38524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαπλέω</h1><div class=\"entry-meta\"><span>DGP · ordem 2374 na letra σ · nº geral 38524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer uma travessia junto.</p></section></article>\n<article id=\"entry-dgp-38525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαπολεμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2375 na letra σ · nº geral 38525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sustentar uma guerra até o fim com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαπορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2376 na letra σ · nº geral 38526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estar igualmente em dúvida; expor dúvidas ou questões junto com alguém, dat., sobre algo, περί, ὑπέρ e gen.</p></section></article>\n<article id=\"entry-dgp-38527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαπράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2377 na letra σ · nº geral 38527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át -άττω 1 levar a termo, exercer junto (uma magistratura) 2 cumprir, realizar com ♦ méd. 3 negociar ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιασκοπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2378 na letra σ · nº geral 38528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">examinar algo, ac., junto com alguém, dat. ou μετά e gen.</p></section></article>\n<article id=\"entry-dgp-38529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαστρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 2379 na letra σ · nº geral 38529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">distorcer, perverter ou corromper junto.</p></section></article>\n<article id=\"entry-dgp-38530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιασῴζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2380 na letra σ · nº geral 38530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ajudar a preservar, a defender, a salvar 2 salvar ou conservar com ou ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαταλαιπωρέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2381 na letra σ · nº geral 38531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνδιαταλαιπωρέω-ῶ suportar a infelicidade junto com alguém, dat.; ser companheiro de infortúnio.</p></section></article>\n<article id=\"entry-dgp-38532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαταράσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2382 na letra σ · nº geral 38532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω causar perturbação; provocar desordem.</p></section></article>\n<article id=\"entry-dgp-38533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιατείνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2383 na letra σ · nº geral 38533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estender ou alongar com ou ao mesmo tempo; ajudar a estender ♦ méd. 2 estender-se junto.</p></section></article>\n<article id=\"entry-dgp-38534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιατελέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2384 na letra σ · nº geral 38534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perseverar com ou ao mesmo tempo; continuar junto até o fim.</p></section></article>\n<article id=\"entry-dgp-38535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιατίθημι</h1><div class=\"entry-meta\"><span>DGP · ordem 2385 na letra σ · nº geral 38535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dispor, arranjar algo, ac., com alguém, dat. 2 ajudar a dispor ♦ pas. 3 ser disposto ou afetado conjuntamente.</p></section></article>\n<article id=\"entry-dgp-38536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιατρέπομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2386 na letra σ · nº geral 38536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perturbar-se ao mesmo tempo que alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιατρέφω</h1><div class=\"entry-meta\"><span>DGP · ordem 2387 na letra σ · nº geral 38537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criar uma pessoa, ac., junto com outra, dat.</p></section></article>\n<article id=\"entry-dgp-38538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιατρίβω</h1><div class=\"entry-meta\"><span>DGP · ordem 2388 na letra σ · nº geral 38538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 empregar junto com alguém, dat.: σ. αἰῶνα ou χρόνον plut. passar o tempo junto 2 passar o tempo com; viver com alguém, dat. ou μετά e gen. 3 seguir as lições de alguém, dat.: οἱ τῷ Σωκράτει συνδιατρίβοντες xen. os discípulos de Sócrates 4 ocupar-se de algo, dat.</p></section></article>\n<article id=\"entry-dgp-38539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαφέρω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2389 na letra σ · nº geral 38539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνδιαφέρω (fut. συνδιοίσω, aor.1 συνδιήνεγκα, aor. jôn. συνδιήνεικα) 1 transportar consigo ♦ at. e méd. 2 suportar (guerra), ac., junto com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαφθείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 2390 na letra σ · nº geral 38540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 destruir uma coisa, ac., junto com outra, dat. ♦ pas. 2 ser destruído ou perecer juntamente com algo, dat.</p></section></article>\n<article id=\"entry-dgp-38541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαφυλάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2391 na letra σ · nº geral 38541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω 1 ajudar alguém, dat., a zelar ou preservar algo, ac. 2 conservar algo, ac., juntamente com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαχειμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2392 na letra σ · nº geral 38542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar o inverno junto com alguém, dat. ou μετά e gen.</p></section></article>\n<article id=\"entry-dgp-38543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαχειρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2393 na letra σ · nº geral 38543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ajudar a executar.</p></section></article>\n<article id=\"entry-dgp-38544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιαχέω</h1><div class=\"entry-meta\"><span>DGP · ordem 2394 na letra σ · nº geral 38544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dissolver algo, ac., em (líquido), dat.</p></section></article>\n<article id=\"entry-dgp-38545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδίδωμι,</h1><div class=\"entry-meta\"><span>DGP · ordem 2395 na letra σ · nº geral 38545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνδίδωμι 1 contribuir, cooperar com algo, ac., para algo, εἰς e ac. 2 Medic., intr. (sintoma) atenuar-se; abrandar-se 3 intr. difundir-se; espalhar-se por, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-38546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιεκπίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 2396 na letra σ · nº geral 38546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">precipitar-se ao mesmo tempo; evadir-se junto.</p></section></article>\n<article id=\"entry-dgp-38547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιέξειμι</h1><div class=\"entry-meta\"><span>DGP · ordem 2397 na letra σ · nº geral 38547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expor ou relatar ao mesmo tempo 2 percorrer junto com, dat.</p></section></article>\n<article id=\"entry-dgp-38548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιημέρευσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2398 na letra σ · nº geral 38548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">frequentação; convivência; convívio. 〈συνδιημερεύω〉</p></section></article>\n<article id=\"entry-dgp-38549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιημερεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2399 na letra σ · nº geral 38549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar os dias com alguém, dat. ou μετά e gen.</p></section></article>\n<article id=\"entry-dgp-38550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιήνεικα</h1><div class=\"entry-meta\"><span>DGP · ordem 2400 na letra σ · nº geral 38550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. συνδιαφέρω.</p></section></article>\n<article id=\"entry-dgp-38551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδικέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2401 na letra σ · nº geral 38551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 defender na justiça; advogar por; tomar a defesa de alguém, dat. 2 atuar como advogado de alguém, dat. 〈σύνδικος〉</p></section></article>\n<article id=\"entry-dgp-38552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνδικος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2402 na letra σ · nº geral 38552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξύνδικος, ου (ὁ, ἡ) 1 Jur. advogado de defesa de alguém, gen. 2 em Atenas, advogado público, designado para defender os interesses da cidade ou de uma tribo ♦ adj. 3 que pertence igualmente a, gen.; comum. 〈σύν, δίκη〉</p></section></article>\n<article id=\"entry-dgp-38553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδίκως</h1><div class=\"entry-meta\"><span>DGP · ordem 2403 na letra σ · nº geral 38553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. conjuntamente.</p></section></article>\n<article id=\"entry-dgp-38554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιοράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2404 na letra σ · nº geral 38554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ver a fundo ao mesmo tempo; examinar juntamente.</p></section></article>\n<article id=\"entry-dgp-38555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδισκεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2405 na letra σ · nº geral 38555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançar o disco ou a lança juntamente com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδιώκω</h1><div class=\"entry-meta\"><span>DGP · ordem 2406 na letra σ · nº geral 38556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perseguir com ou junto 2 Jur. perseguir na justiça junto.</p></section></article>\n<article id=\"entry-dgp-38557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδοκέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2407 na letra σ · nº geral 38557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνδοκέω-ῶ at. e méd. parecer bom também; ser opinião também de alguém, dat.: ταῦτα κἀμοὶ συνδοκεῖ ar. essa é também minha opinião, συνεδόκει οὖν καὶ ἐμοὶ ὑπερμέγεθες εἶναι ἔργον τὸ καλῶς ἄρχειν xen. também eu era da opinião de que a arte de bem comandar é uma coisa extraordinária, λόγον τοῖς ἐπιεικεστάτοις καὶ πρεσβυτάτοις ξυνδεδογμένον ὡς ὄντως ὀρθός ἐστιν plat. lei sobre a qual os mais justos e os mais velhos são de parecer de que é verdadeiramente correta; ac. abs., ἐγὼ οὖν Θηραμένην τουτονὶ ἐξαλείφω ἐκ τοῦ καταλόγου, συνδοκοῦν ἅπασιν ἡμῖν xen. portanto, eu excluo da lista o nome de Terâmenes aqui presente, de comum acordo com todos nós, συνδόξαν τῷ πατρὶ καὶ τῇ μητρὶ γαμεῖ τὴν Κυαξάρου θυγατέρα xen. com o consentimento do pai e da mãe, ele desposa a filha de Ciaxares.</p></section></article>\n<article id=\"entry-dgp-38558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδοκιμάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2408 na letra σ · nº geral 38558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">examinar com ou ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδοξάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2409 na letra σ · nº geral 38559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aprovar junto 2 estar de acordo com, dat. 3 bíbl. glorificar junto.</p></section></article>\n<article id=\"entry-dgp-38560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδόξαν</h1><div class=\"entry-meta\"><span>DGP · ordem 2410 na letra σ · nº geral 38560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. at. n. de συνδοκέω.</p></section></article>\n<article id=\"entry-dgp-38561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδουλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2411 na letra σ · nº geral 38561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser companheiro de escravidão de alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδούλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2412 na letra σ · nº geral 38562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de σύνδουλος.</p></section></article>\n<article id=\"entry-dgp-38563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνδουλος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2413 na letra σ · nº geral 38563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheiro de escravidão. 〈σύν, δοῦλος〉</p></section></article>\n<article id=\"entry-dgp-38564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδραμεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 2414 na letra σ · nº geral 38564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de συντρέχω.</p></section></article>\n<article id=\"entry-dgp-38565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδράω,</h1><div class=\"entry-meta\"><span>DGP · ordem 2415 na letra σ · nº geral 38565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξυνδράω-ῶ ajudar alguém, dat., a fazer algo, ac.; agir com.</p></section></article>\n<article id=\"entry-dgp-38566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδρομάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2416 na letra σ · nº geral 38566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = σύνδρομος.</p></section></article>\n<article id=\"entry-dgp-38567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδρομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2417 na letra σ · nº geral 38567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">afluência de multidão. 〈συνδραμεῖν〉</p></section></article>\n<article id=\"entry-dgp-38568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνδρομος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2418 na letra σ · nº geral 38568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξύνδρομος, ος, ον 1 que corre junto com; que acompanha a correr, gen. 2 concomitante; coincidente com, dat.: πρὶν ἐλθεῖν τὴν ὥραν τὴν τοῦ τρυγᾶν Ἀρκτούρῳ σύνδρομον plat. antes da chegada da estação da colheita, que chega com Arcturo ♦ σύνδρομα adv. 3 com o mesmo passo; na mesma corrida: σ. πορεύεσθαι τῷ ἄριστα γεγυμνασμένῳ plat. acompanhar na corrida o mais bem treinado ♦ ὁ σύνδρομος 4 encruzilhada 5 entrechoque (de rochas).</p></section></article>\n<article id=\"entry-dgp-38569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδρόμως</h1><div class=\"entry-meta\"><span>DGP · ordem 2419 na letra σ · nº geral 38569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδυάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2420 na letra σ · nº geral 38570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pas. aor. συνεδυάσθην, perf. συνδεδύασμαι) 1 unir dois a dois; acoplar uma coisa ou pessoa, ac., a outra, πρός e ac. ♦ pas. 2 ser tomado de dois em dois; ser acoplado 3 ter relações sexuais; copular com, dat. 4 associar-se a; combinar com algo ou alguém, dat. 5 Jur. estar em conluio com alguém, dat. 〈συνδυάς〉</p></section></article>\n<article id=\"entry-dgp-38571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδυάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2421 na letra σ · nº geral 38571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) que forma um casal.</p></section></article>\n<article id=\"entry-dgp-38572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνδυασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2422 na letra σ · nº geral 38572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acoplamento; combinação; união de duas pessoas ou coisas 2 acasalamento; cópula. 〈συνδυάζω〉</p></section></article>\n<article id=\"entry-dgp-38573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνδυο</h1><div class=\"entry-meta\"><span>DGP · ordem 2423 na letra σ · nº geral 38573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. indecl. conjunto de dois; par.</p></section></article>\n<article id=\"entry-dgp-38574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέαξαν</h1><div class=\"entry-meta\"><span>DGP · ordem 2424 na letra σ · nº geral 38574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl., συνέαξε 3ª sing., aor. de συνάγνυμι.</p></section></article>\n<article id=\"entry-dgp-38575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεαρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2425 na letra σ · nº geral 38575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar a primavera com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέβησαν</h1><div class=\"entry-meta\"><span>DGP · ordem 2426 na letra σ · nº geral 38576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. de συμβαίνω.</p></section></article>\n<article id=\"entry-dgp-38577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέγγιστα</h1><div class=\"entry-meta\"><span>DGP · ordem 2427 na letra σ · nº geral 38577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. σύνεγγυς.</p></section></article>\n<article id=\"entry-dgp-38578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεγγράφω</h1><div class=\"entry-meta\"><span>DGP · ordem 2428 na letra σ · nº geral 38578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inscrever junto ou registrar junto com alguém, dat.</p></section></article>\n<article id=\"entry-dgp-38579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεγγυάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2429 na letra σ · nº geral 38579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 garantir junto; unir-se em fiança ♦ méd. 2 assumir compromisso de casamento junto 3 abonar ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνεγγυς,</h1><div class=\"entry-meta\"><span>DGP · ordem 2430 na letra σ · nº geral 38580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ξύνεγγυς (superl. συνέγγιστα) adv. 1 (lugar) bem perto; muito próximo de, gen. ou dat. 2 (tempo) muito proximamente 3 (afinidade) em relação de afinidade; de mesma natureza: καὶ τούτοις ἄλλα ὀνόματα σύνεγγυς artt. e demais palavras afins a essas ♦ οἱ σύνεγγυς 4 as pessoas da mesma classe ♦ τὸ σύνεγγυς 5 vizinhança.</p></section></article>\n<article id=\"entry-dgp-38581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεγείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 2431 na letra σ · nº geral 38581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ajudar a despertar, a reviver, a reanimar ♦ pas. 2 despertar junto 3 bíbl. reanimar-se ao mesmo tempo.</p></section></article>\n<article id=\"entry-dgp-38582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεδρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2432 na letra σ · nº geral 38582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tomar parte de assembleia deliberativa 2 realizar sessões para deliberar sobre algo, ὑπέρ e gen. 3 Gram. estar em relação com. 〈σύνεδρος〉</p></section></article>\n<article id=\"entry-dgp-38583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεδρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2433 na letra σ · nº geral 38583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assembleia; reunião; encontro (de amigos) 2 assembleia deliberativa 3 hábito gregário. 〈σύνεδρος〉</p></section></article>\n<article id=\"entry-dgp-38584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέδριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2434 na letra σ · nº geral 38584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assembléia deliberativa 2 conselho de anfictiões 3 assembléia geral; congresso dos gregos após as Guerras Médicas 4 colégio ou corporação judiciária, ref. ao Areópago 5 Senado em Roma, em Cartago 6 bíbl. sinédrio 7 conselho de guerra 8 sala do conselho. 〈σύνεδρος〉</p></section></article>\n<article id=\"entry-dgp-38585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύνεδρος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2435 na letra σ · nº geral 38585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ξύνεδρος, ος, ον 1 que senta com ou perto de, dat. 2 que se reúne para deliberar 3 membro de assembléia deliberativa 4 deputado em assembléia, em congresso 5 pl. reunião de membros de uma assembléia; assembléia; congresso; corporação 6 unido um a outro. 〈σύν, ἕδρα〉</p></section></article>\n<article id=\"entry-dgp-38586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεείκοσι,</h1><div class=\"entry-meta\"><span>DGP · ordem 2436 na letra σ · nº geral 38586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ξυνεείκοσι num. indecl. grupo de vinte; de vinte em vinte.</p></section></article>\n<article id=\"entry-dgp-38587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεέργω</h1><div class=\"entry-meta\"><span>DGP · ordem 2437 na letra σ · nº geral 38587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. συνέεργον e aor. ép. συνεέργαθον) = συνέργω.</p></section></article>\n<article id=\"entry-dgp-38588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέζευξα</h1><div class=\"entry-meta\"><span>DGP · ordem 2438 na letra σ · nº geral 38588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.1 de συζεύγνυμι.</p></section></article>\n<article id=\"entry-dgp-38589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεζήτουν</h1><div class=\"entry-meta\"><span>DGP · ordem 2439 na letra σ · nº geral 38589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. de συζητέω.</p></section></article>\n<article id=\"entry-dgp-38590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνέηκα</h1><div class=\"entry-meta\"><span>DGP · ordem 2440 na letra σ · nº geral 38590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.1 jôn. de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεθέλω</h1><div class=\"entry-meta\"><span>DGP · ordem 2441 na letra σ · nº geral 38591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tomar uma decisão de comum acordo sobre algo, dat.</p></section></article>\n<article id=\"entry-dgp-38592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2442 na letra σ · nº geral 38592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pas. aor. συνειθίσθην, perf. συνείθισμαι) 1 habituar a 2 no aor.1 e perf., estar habituado a; συνειθισμένον ἦν LÍS. era costume ♦ pas. 3 habituar-se a, inf.</p></section></article>\n<article id=\"entry-dgp-38593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεθιστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 2443 na letra σ · nº geral 38593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de συνεθίζω.</p></section></article>\n<article id=\"entry-dgp-38594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνειδέναι</h1><div class=\"entry-meta\"><span>DGP · ordem 2444 na letra σ · nº geral 38594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. de σύνοιδα.</p></section></article>\n<article id=\"entry-dgp-38595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνείδησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2445 na letra σ · nº geral 38595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conhecimento; consciência 2 bíbl. consciência moral; escrúpulo. 〈σύνοιδα〉</p></section></article>\n<article id=\"entry-dgp-38596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνειδήσω</h1><div class=\"entry-meta\"><span>DGP · ordem 2446 na letra σ · nº geral 38596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de σύνοιδα.</p></section></article>\n<article id=\"entry-dgp-38597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνειδώς, υῖα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 2447 na letra σ · nº geral 38597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. de σύνοιδα.</p></section></article>\n<article id=\"entry-dgp-38598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνεῖεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2448 na letra σ · nº geral 38598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. opt. aor.2 de συνίημι.</p></section></article>\n<article id=\"entry-dgp-38599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνείκοσι</h1><div class=\"entry-meta\"><span>DGP · ordem 2449 na letra σ · nº geral 38599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">συνεείκοσι.</p></section></article>\n<article id=\"entry-dgp-38600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συνείλας, ασα, αν</h1><div class=\"entry-meta\"><span>DGP · ordem 2450 na letra σ · nº geral 38600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.1 de συνίλλω.</p></section></article>\n";
